public void Nakagin_Capsule_Tower_Copy_Paste_Roundtrip()
{
    var kit = Tests.LoadAsset<Kit>("metabolism.kit.compose.json");
    var design = kit.Designs.First(d => d.Name == "Nakagin Capsule Tower" && d.Parent == null);
    var selection = Tests.LoadAsset<Selection>("nakagin-capsule-tower.copy.design.selection.compose.json");

    var pieceGuids = selection.Pieces.Select(p => p.Guid).ToList();
    var connectionGuids = selection.Connections.Select(c => c.Guid).ToList();

    // Compute CopyDesign
    var copyDesign = Design.CopyDesign(kit, design, pieceGuids, connectionGuids);

    // Compute PasteDesign without coord
    var pasteDiff = Design.PasteDesign(kit, copyDesign, design, "original");

    // Apply paste diff to target to get the paste design
    var pasteDesignResult = Design.ApplyDiff(Entity<Design>.DeepClone(design)!, pasteDiff);

    // Compute PasteDesign with coord
    var pasteWithCoordDiff = Design.PasteDesign(kit, copyDesign, design, "original", new Coord { U = 10, V = 10 });

    // Save the generated files for cross-language comparison
    var copyJson = Utility.Serialize(copyDesign, "  ");
    var pasteJson = Utility.Serialize(pasteDiff, "  ");
    var pasteDesignJson = Utility.Serialize(pasteDesignResult, "  ");
    var pasteWithCoordJson = Utility.Serialize(pasteWithCoordDiff, "  ");
    System.IO.File.WriteAllText(Path.Combine(Tests.AssetsPath, "nakagin-capsule-tower.copy.design.compose.json"), copyJson);
    System.IO.File.WriteAllText(Path.Combine(Tests.AssetsPath, "nakagin-capsule-tower.paste.design.diff.compose.json"), pasteJson);
    System.IO.File.WriteAllText(Path.Combine(Tests.AssetsPath, "nakagin-capsule-tower.paste.design.compose.json"), pasteDesignJson);
    System.IO.File.WriteAllText(Path.Combine(Tests.AssetsPath, "nakagin-capsule-tower.paste.with-coord.design.diff.compose.json"), pasteWithCoordJson);

